import { isNullOrUndefined } from '@syncfusion/ej2-base';
import { SanitizeHtmlHelper } from '@syncfusion/ej2-base';
/**
 * Helper class for style operations in Document Editor
 *
 * @private
 */
export class StylesHelper {
    static ensureStyleSheet() {
        if (!StylesHelper.dynamicStyleSheet) {
            StylesHelper.dynamicStyleSheet = new CSSStyleSheet();
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            document.adoptedStyleSheets = [
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                ...document.adoptedStyleSheets,
                StylesHelper.dynamicStyleSheet
            ];
        }
        return StylesHelper.dynamicStyleSheet;
    }
    static getDynamicStyleClass(styleString) {
        if (!styleString) {
            return '';
        }
        /* eslint-disable */
        const existingClass = StylesHelper.styleClassMap[styleString];
        if (existingClass) {
            return existingClass;
        }
        const className = 'e-de-style-gallery-' + StylesHelper.styleCounter++;
        const styleSheet = StylesHelper.ensureStyleSheet();
        styleSheet.insertRule('.' + className + ' {' + styleString + '}', styleSheet.cssRules.length);
        /* eslint-disable */
        StylesHelper.styleClassMap[styleString] = className;
        return className;
    }
    /**
     * Get style items for gallery
     *
     * @param {DocumentEditor} documentEditor - Document editor instance
     * @param {L10n} localObj - Localization object
     * @returns {RibbonGalleryItemModel[]} Array of style gallery items
     */
    static getStyleItems(documentEditor, localObj) {
        const styles = [];
        // Get styles from document's stylesMap
        if (documentEditor && documentEditor.documentHelper && documentEditor.documentHelper.stylesMap) {
            const stylesMap = documentEditor.documentHelper.stylesMap;
            // First add important default styles in proper order
            const defaultStyleNames = [
                'Normal', 'Heading 1', 'Heading 2', 'Heading 3', 'Heading 4',
                'Title', 'Subtitle', 'Quote', 'Emphasis', 'Strong'
            ];
            // Process styles by type: Paragraph, Character, and Linked
            const paragraphStyles = stylesMap.get('Paragraph') || [];
            const characterStyles = stylesMap.get('Character') || [];
            const linkedStyles = stylesMap.get('Linked') || [];
            // Create lookup maps for faster access
            const stylesMaps = StylesHelper.createStyleMaps(paragraphStyles, linkedStyles, characterStyles);
            // Add default styles first in the specified order
            StylesHelper.addDefaultStyles(styles, defaultStyleNames, stylesMaps, localObj);
            // Track added styles to avoid duplicates
            const addedStylesMap = {};
            /* eslint-disable */
            defaultStyleNames.forEach((name) => { if (localObj.getConstant(name) !== '')
                addedStylesMap[localObj.getConstant(name)] = true; });
            // defaultStyleNames.forEach((name: string) => {
            //     Object.prototype.hasOwnProperty.call(addedStylesMap, name) || (addedStylesMap[name] = true);
            // });
            // Add remaining styles
            StylesHelper.addRemainingStyles(styles, paragraphStyles, linkedStyles, addedStylesMap);
            //Add character styles
            for (const linkedStyle of linkedStyles) {
                for (const charStyle of characterStyles) {
                    if (linkedStyle['StyleName'] + ' Char' === charStyle['StyleName']) {
                        characterStyles.splice(characterStyles.indexOf(charStyle), 1);
                        break;
                    }
                }
            }
            StylesHelper.addRemainingStyles(styles, characterStyles, linkedStyles, addedStylesMap);
        }
        // If no styles found, provide some defaults
        if (styles.length === 0) {
            styles.push({
                content: localObj.getConstant('Normal'),
                cssClass: 'e-de-gallery-normal',
                htmlAttributes: {
                    title: localObj.getConstant('Normal')
                }
            });
            styles.push({
                content: localObj.getConstant('Heading 1'),
                cssClass: 'e-de-gallery-heading1',
                htmlAttributes: {
                    title: localObj.getConstant('Heading 1')
                }
            });
        }
        return styles;
    }
    static createStyleMaps(paragraphStyles, linkedStyles, characterStyles) {
        const createStyleMap = (styles) => {
            const map = {};
            for (let i = 0; i < styles.length; i++) {
                map[styles[parseInt(i.toString(), 10)].StyleName] = styles[parseInt(i.toString(), 10)];
            }
            return map;
        };
        return {
            paragraphStyleMap: createStyleMap(paragraphStyles),
            linkedStyleMap: createStyleMap(linkedStyles),
            characterStyleMap: createStyleMap(characterStyles)
        };
    }
    static addDefaultStyles(styles, defaultStyleNames, stylesMaps, localObj) {
        const { paragraphStyleMap, linkedStyleMap, characterStyleMap } = stylesMaps;
        for (let i = 0; i < defaultStyleNames.length; i++) {
            const styleName = localObj.getConstant(defaultStyleNames[parseInt(i.toString(), 10)]);
            // Direct lookup is much faster than looping
            const styleInfo = paragraphStyleMap[styleName] ||
                linkedStyleMap[styleName] ||
                characterStyleMap[styleName];
            if (styleInfo) {
                styles.push({
                    content: styleName,
                    cssClass: StylesHelper.getDynamicStyleClass(styleInfo.Style),
                    htmlAttributes: {
                        title: styleName
                    }
                });
            }
        }
    }
    static addRemainingStyles(styles, paragraphStyles, linkedStyles, addedStylesMap) {
        // Add remaining paragraph styles
        for (let i = 0; i < paragraphStyles.length; i++) {
            const style = paragraphStyles[parseInt(i.toString(), 10)];
            if (!addedStylesMap[style.StyleName]) {
                styles.push({
                    content: style.StyleName,
                    cssClass: StylesHelper.getDynamicStyleClass(style.Style),
                    htmlAttributes: {
                        title: style.StyleName
                    }
                });
                addedStylesMap[style.StyleName] = true;
            }
        }
        // Add linked styles
        for (let i = 0; i < linkedStyles.length; i++) {
            const style = linkedStyles[parseInt(i.toString(), 10)];
            if (!addedStylesMap[style.StyleName]) {
                styles.push({
                    content: style.StyleName,
                    cssClass: StylesHelper.getDynamicStyleClass(style.Style),
                    htmlAttributes: {
                        title: style.StyleName
                    }
                });
                addedStylesMap[style.StyleName] = true;
            }
        }
    }
    /**
     * Get the current style name from selection
     *
     * @param {DocumentEditor} documentEditor - Document editor instance
     * @returns {string} The current style name
     */
    static getCurrentStyleName(documentEditor, localObj) {
        if (!documentEditor || !documentEditor.selection) {
            return 'Normal';
        }
        const characterFormat = documentEditor.selection.characterFormat;
        const paragraphFormat = documentEditor.selection.paragraphFormat;
        if (characterFormat && characterFormat.styleName &&
            characterFormat.styleName !== 'Default Paragraph Font') {
            const localeValue = localObj.getConstant(characterFormat.styleName);
            return (isNullOrUndefined(localeValue) || localeValue == '') ? characterFormat.styleName : localeValue;
        }
        else if (paragraphFormat && paragraphFormat.styleName) {
            const localeValue = localObj.getConstant(paragraphFormat.styleName);
            return (isNullOrUndefined(localeValue) || localeValue == '') ? paragraphFormat.styleName : localeValue;
        }
        return 'Normal';
    }
    /**
     * Find the index of a style in the gallery items
     *
     * @param {string} styleName - Style name to find
     * @param {RibbonGalleryItemModel[]} items - Gallery items array
     * @returns {number} Index of the style or -1 if not found
     */
    static findStyleIndex(styleName, items) {
        if (!items) {
            return -1;
        }
        for (let i = 0; i < items.length; i++) {
            if (items[parseInt(i.toString(), 10)] && items[parseInt(i.toString(), 10)].content === styleName) {
                return i;
            }
        }
        return -1;
    }
    /**
     * Apply a style to the document
     *
     * @param {DocumentEditor} documentEditor - Document editor instance
     * @param {string} styleName - Style name to apply
     * @returns {void}
     */
    static applyStyle(documentEditor, styleName) {
        if (!documentEditor.isReadOnly && documentEditor.editorModule) {
            documentEditor.editorModule.applyStyle(styleName, true);
        }
    }
    /**
     * Update style names in ComboBox
     *
     * @param {DocumentEditor} documentEditor - Document editor instance
     * @param {any} style - ComboBox instance
     * @param {L10n} localObj - Localization object
     * @returns {string} Current style name
     */
    static updateStyleNames(documentEditor, style, localObj) {
        const styleName = !isNullOrUndefined(style.itemData) ? style.itemData.StyleName : undefined;
        const stylesMap = documentEditor.documentHelper.stylesMap;
        const paraStyles = stylesMap.get('Paragraph') ? stylesMap.get('Paragraph') : [];
        const linkedStyles = stylesMap.get('Linked') ? stylesMap.get('Linked') : [];
        const charStyles = stylesMap.get('Character') ? stylesMap.get('Character') : [];
        // Filter out character styles that are part of linked styles
        for (const linkedStyle of linkedStyles) {
            for (let i = 0; i < charStyles.length; i++) {
                const charStyle = charStyles[parseInt(i.toString(), 10)];
                if (linkedStyle['StyleName'] + ' Char' === charStyle['StyleName']) {
                    charStyles.splice(i, 1);
                    break;
                }
            }
        }
        // Update ComboBox data source
        style.dataSource = paraStyles.concat(linkedStyles, charStyles);
        return styleName;
    }
    /* eslint-enable */
    /**
     * Apply style value from ComboBox selection
     *
     * @param {DocumentEditor} documentEditor - Document editor instance
     * @param {any} args - ComboBox change event arguments
     * @returns {void}
     */
    static applyStyleValue(documentEditor, args) {
        if (!documentEditor.isReadOnly && documentEditor.editorModule) {
            const styleName = documentEditor.stylesDialogModule.getStyleName(SanitizeHtmlHelper.sanitize(args.itemData.StyleName));
            if (!isNullOrUndefined(documentEditor.documentHelper.styles.findByName(styleName))) {
                documentEditor.editorModule.applyStyle(styleName, true);
                // Update tree view if options pane is showing
                const treeViewResult = document.getElementById(documentEditor.containerId + '_treeDiv');
                if (!isNullOrUndefined(treeViewResult) &&
                    !isNullOrUndefined(documentEditor.optionsPaneModule) &&
                    documentEditor.optionsPaneModule.isOptionsPaneShow &&
                    documentEditor.optionsPaneModule.isHeadingTab) {
                    treeViewResult.innerHTML = '';
                    documentEditor.optionsPaneModule.data = documentEditor.optionsPaneModule.dataForTreeview();
                    documentEditor.optionsPaneModule.initHeadingTab();
                }
            }
        }
    }
}
StylesHelper.styleClassMap = {};
StylesHelper.styleCounter = 0;
