    /**
     * /* Here is the explanation for the code below:
        1. When there are multiple sections in a document, the first section is the parent section of the other sections.
        2. If you change the page width or header distance of the parent section, the child section will inherit the page width or header distance of the parent section.
        3. So when you change the page width or header distance of the parent section, the child section should be relayouted.
     * @private
     */
    comparePageWidthAndMargins(parentHFWidget, page) {
        let headerFooterType = parentHFWidget.headerFooterType;
        let currentHFWidget;
        let isHeader = headerFooterType.indexOf('Header') != -1;
        let isRelayout = false;
        if (isHeader) {
            currentHFWidget = page.headerWidgetIn;
        }
        else {
            currentHFWidget = page.footerWidgetIn;
        }
        if (!isNullOrUndefined(currentHFWidget)) {
            const parentSectionFormat = parentHFWidget.sectionFormat;
            const currentSectionFormat = currentHFWidget.sectionFormat;
            if (!isNullOrUndefined(parentSectionFormat) && !isNullOrUndefined(currentSectionFormat)) {
                if (isHeader) {
                    const currentLen = currentHFWidget.childWidgets.length;
                    const parentLen = parentHFWidget.childWidgets.length;
                    const lastChildYChanged = currentLen > 0 && parentLen > 0 && currentHFWidget.childWidgets[currentLen - 1].y !== parentHFWidget.childWidgets[parentLen - 1].y;
                    if (parentHFWidget.width != currentHFWidget.width || parentSectionFormat.headerDistance != currentSectionFormat.headerDistance || lastChildYChanged) {
                        isRelayout = true;
                    }
                }
                else {
                    if (parentHFWidget.width != currentHFWidget.width || parentSectionFormat.footerDistance != currentSectionFormat.footerDistance) {
                        isRelayout = true;
                    }
                }
            }
            if (isRelayout) {
                parentHFWidget.height = 0;
                this.documentHelper.layout.clearBlockWidget(parentHFWidget.childWidgets, false, true, true);
                this.owner.viewer.updateHFClientArea(parentHFWidget.sectionFormat, isHeader);
                parentHFWidget = this.documentHelper.layout.layoutHeaderFooterItems(this.owner.viewer, parentHFWidget);
            }
        }
    }
    /**
     * @private
     */
    shiftBlockOnHeaderFooterEnableDisable() {
        for (let i = 0; i < this.documentHelper.headersFooters.length; i++) {
            let headerFooter = this.documentHelper.headersFooters[i];
            let bodywidget = this.getBodyWidgetInternal(i, 0);
            if (isNullOrUndefined(bodywidget)) {
                continue;
            }
            let sectionFormat = bodywidget.sectionFormat;
            for (let key of Object.keys(headerFooter)) {
                let widget = headerFooter[key];
                if (widget.isEmpty) {
                    this.owner.editorModule.shiftPageContent(widget.headerFooterType, sectionFormat);
                }
            }
        }
    }
    /**
     * @private
     */
    updateTextPositionForBlockContainer(widget) {
        let block = widget.firstChild;
        if (block instanceof TableWidget) {
            block = this.getFirstBlockInFirstCell(block);
            if (block instanceof TableWidget) {
                block = this.getFirstBlockInFirstCell(block);
            }
        }
        this.selectParagraphInternal(block, true);
    }
    getPageStartEndPosition(page) {
        const firstBodyWidget = page.bodyWidgets[0];
        const lastBodyWidget = page.bodyWidgets[page.bodyWidgets.length - 1];
        // Updating the start and end based on the page.
        if (firstBodyWidget && lastBodyWidget) {
            let startPosition = new TextPosition(this.owner);
            let endPosition = new TextPosition(this.owner);
            let firstBlock = firstBodyWidget.firstChild;
            let lastBlock = lastBodyWidget.lastChild;
            if (firstBlock && lastBlock) {
                if (firstBlock instanceof TableWidget) {
                    firstBlock = this.getFirstBlockInFirstCell(firstBlock);
                    while (firstBlock instanceof TableWidget) {
                        firstBlock = this.getFirstBlockInFirstCell(firstBlock);
                    }
                }
                let line = firstBlock.firstChild;
                startPosition.setPosition(line, true);
                if (lastBlock instanceof TableWidget) {
                    lastBlock = this.getLastBlockInLastCell(lastBlock, true);
                    while (lastBlock instanceof TableWidget) {
                        lastBlock = this.getLastBlockInLastCell(lastBlock, true);
                    }
                }
                line = lastBlock.lastChild;
                let endOffset = line.getEndOffset();
                endPosition.setPositionParagraph(line, endOffset);
                return { startPosition, endPosition };
            }
        }
        return undefined;
    }
