            if (this.right !== 0) {
                right = (this.right * this.cropWidthScale) / 100;
            }
            if (this.bottom !== 0) {
                bottom = (this.bottom * this.cropHeightScale) / 100;
            }
            this.cropWidth = (this.cropWidthScale - (this.cropX + right));
            this.cropHeight = (this.cropHeightScale - (this.cropY + bottom));
