    clearFieldElementRevisions(inline, revision) {
        let revisions = revision;
        for (let i = 0; i < revision.length; i++) {
            let currentRevision = revisions[i];
            for (let j = 0; j < currentRevision.getRange().length; j++) {
                if (currentRevision.getRange()[j] === inline) {
                    for (let k = j; k < currentRevision.getRange().length; k) {
                        if (currentRevision.getRange()[j] instanceof FieldElementBox && currentRevision.getRange()[j].fieldType === 1 && currentRevision.getRange()[j].fieldBegin === inline) {
                            currentRevision.removeCurrentRevisionFromItem(currentRevision.getRange()[j]);
                            if (currentRevision.getRange().length === 0) {
                                this.owner.revisions.remove(currentRevision);
                            }
                            break;
                        }
                        currentRevision.removeCurrentRevisionFromItem(currentRevision.getRange()[j]);
                    }
                }
            }
        }
    }
    /**
     * @private
     * @returns {void}
     */
    addRemovedRevisionInfo(currentElement, spittedElement) {
        for (let i = 0; i < currentElement.revisionLength; i++) {
            let revisionId = currentElement.getRevision(i).revisionID;
            if (!isNullOrUndefined(spittedElement)) {
                spittedElement.removedIds.push(revisionId);
            }
            else {
                currentElement.removedIds.push(revisionId);
            }
        }
    }
    /**
     * @private
     * @returns {void}
     */
    removeEmptyLine(paragraph) {
        if (paragraph.childWidgets.length > 1) {
            for (let i = 0; i < paragraph.childWidgets.length; i++) {
                let lineWidget = paragraph.childWidgets[i];
                if (lineWidget.children.length === 0 && paragraph.childWidgets.length > 1) {
                    paragraph.childWidgets.splice(i, 1);
                    i--;
                }
            }
        }
    }
